  <div class="loans-list-wrapper">
    <!-- Barra de resumo -->
    <div class="summary-bar mb-3">
      <b-row align-v="center">
        <b-col md="4">
          <div class="d-flex align-items-center">
            <div class="summary-icon mr-2" :class="statusClass">
              <b-icon :icon="statusIcon" font-scale="1.1"></b-icon>
            </div>
            <div>
              <div class="summary-count">{{ pagination.totalItems }}</div>
              <div class="summary-label text-muted">{{ pagination.totalItems === 1 ? 'financiamento' : 'financiamentos' }}</div>
            </div>
          </div>
        </b-col>
        <b-col md="4" class="text-center">
          <div class="summary-total-label text-muted">Montante (Página)</div>
          <div class="summary-total-value font-weight-bold">{{ formatMoney(pageTotal) }}</div>
        </b-col>
        <b-col md="4" class="text-right">
          <b-input-group size="sm" class="search-box">
            <b-input-group-prepend is-text class="bg-light border-right-0">
              <b-icon icon="search" variant="secondary" font-scale="0.85"></b-icon>
            </b-input-group-prepend>
            <b-form-input
              type="text"
              class="border-left-0 bg-light"
              v-model="searchQuery"
              @input="onSearchInput"
              placeholder="Pesquisar por nome, conta..."
            ></b-form-input>
            <b-input-group-append v-if="searchQuery">
              <b-button variant="outline-secondary" size="sm" @click="clearSearch">
                <b-icon icon="x"></b-icon>
              </b-button>
            </b-input-group-append>
          </b-input-group>
        </b-col>
      </b-row>
    </div>

    <!-- Loading -->
    <div v-if="loadingLoans" class="text-center py-5">
      <b-spinner variant="success" small class="mr-2"></b-spinner>
      <span class="text-muted">A carregar financiamentos...</span>
    </div>

    <!-- Tabela -->
    <div v-else-if="loanList.length === 0" class="empty-state text-center py-5">
      <b-icon icon="inbox" font-scale="2.5" class="text-muted mb-2"></b-icon>
      <p class="text-muted mb-0">Nenhum financiamento encontrado.</p>
    </div>

    <div v-else class="table-responsive">
      <table class="table table-hover table-sm loans-table mb-0">
        <thead>
          <tr class="table-header">
            <th class="pl-3" width="30">#</th>
            <th>Mutuário</th>
            <th class="text-right">Montante</th>
            <th class="text-center">Prestações</th>
            <th class="text-center">Taxa</th>
            <th class="text-center">Gestor</th>
            <th class="text-center">Data</th>
            <th class="text-center" width="60">Acção</th>
          </tr>
        </thead>
        <tbody>
          <tr
            v-for="(loan, index) in loanList"
            :key="loan.id || index"
            class="loan-row"
          >
            <td class="pl-3 text-muted">{{ rowNumber(index) }}</td>
            <td>
              <div class="d-flex align-items-center">
                <b-avatar
                  :text="getCustomerInitials(loan.accountNumber)"
                  size="32"
                  class="avatar-loan mr-2"
                  :variant="avatarVariant(index)"
                ></b-avatar>
                <div>
                  <div class="customer-name">{{ getCustomerName(loan.accountNumber) }}</div>
                  <small class="text-muted">{{ loan.accountNumber }}</small>
                </div>
              </div>
            </td>
            <td class="text-right">
              <span class="amount-value" v-money-format="loan.amount"></span>
            </td>
            <td class="text-center">
              <span class="badge badge-light border px-2">{{ loan.numberOfInstallments }} {{ loan.numberOfInstallments == 1 ? 'mês' : 'meses' }}</span>
            </td>
            <td class="text-center">
              <span class="rate-badge">{{ (loan.interestRate * 100).toFixed(0) }}%</span>
            </td>
            <td class="text-center">
              <small class="text-muted">{{ getCreditManagerName(loan.creditManager) }}</small>
            </td>
            <td class="text-center">
              <small class="text-muted" v-date-format="loan.dateCreated || loan.createdAt"></small>
            </td>
            <td class="text-center">
              <b-button
                size="sm"
                variant="link"
                class="text-primary p-0"
                @click="openCustomerPanel(loan.accountNumber)"
                v-b-tooltip.hover
                title="Ver mutuário"
              >
                <b-icon icon="box-arrow-up-right" font-scale="0.9"></b-icon>
              </b-button>
            </td>
          </tr>
        </tbody>
        <tfoot>
          <tr class="table-footer">
            <td :colspan="2" class="pl-3 font-weight-bold text-muted">Total (Página)</td>
            <td class="text-right font-weight-bold" v-money-format="pageTotal"></td>
            <td :colspan="5"></td>
          </tr>
        </tfoot>
      </table>
    </div>

    <!-- Controles de Paginação -->
    <div
      v-if="pagination.totalPages > 0 && !loadingLoans"
      class="d-flex justify-content-between align-items-center px-3 py-3 border-top mt-2"
    >
      <div class="d-flex align-items-center">
        <small class="text-muted mr-2">Mostrar</small>
        <b-form-select
          size="sm"
          v-model="perPage"
          :options="perPageOptions"
          style="width: 75px"
          @change="onPerPageChange"
        ></b-form-select>
        <small class="text-muted ml-2">por página</small>
      </div>

      <div class="text-center">
        <small class="text-muted">
          Mostrando
          <strong>{{ paginationStart }}</strong> -
          <strong>{{ paginationEnd }}</strong>
          de
          <strong>{{ pagination.totalItems }}</strong>
          financiamentos
        </small>
      </div>

      <nav aria-label="Navegação">
        <ul class="pagination pagination-sm mb-0">
          <li class="page-item" :class="{ disabled: !pagination.hasPrevPage }">
            <a class="page-link" href="#" @click.prevent="goToPage(1)" title="Primeira">
              <b-icon icon="chevron-double-left" font-scale="0.8"></b-icon>
            </a>
          </li>
          <li class="page-item" :class="{ disabled: !pagination.hasPrevPage }">
            <a class="page-link" href="#" @click.prevent="goToPage(pagination.currentPage - 1)" title="Anterior">
              <b-icon icon="chevron-left" font-scale="0.8"></b-icon>
            </a>
          </li>
          <li v-for="page in visiblePages" :key="page" class="page-item" :class="{ active: page === pagination.currentPage }">
            <a class="page-link" href="#" @click.prevent="goToPage(page)">{{ page }}</a>
          </li>
          <li class="page-item" :class="{ disabled: !pagination.hasNextPage }">
            <a class="page-link" href="#" @click.prevent="goToPage(pagination.currentPage + 1)" title="Próxima">
              <b-icon icon="chevron-right" font-scale="0.8"></b-icon>
            </a>
          </li>
          <li class="page-item" :class="{ disabled: !pagination.hasNextPage }">
            <a class="page-link" href="#" @click.prevent="goToPage(pagination.totalPages)" title="Última">
              <b-icon icon="chevron-double-right" font-scale="0.8"></b-icon>
            </a>
          </li>
        </ul>
      </nav>
    </div>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";
import MoneyFormat from "@/utils/moneyFormat";
import moment from "moment";

export default {
  name: "LoansList",

  props: {
    selectLoanList: {
      type: Array,
      default: () => [],
    },
    listType: {
      type: String,
      default: "pending", // "pending" ou "rejected"
    },
  },

  data: () => ({
    today: moment(),
    loanList: [],
    searchQuery: "",
    searchTimeout: null,
    loadingLoans: false,
    perPage: 15,
    perPageOptions: [
      { value: 10, text: "10" },
      { value: 15, text: "15" },
      { value: 25, text: "25" },
      { value: 50, text: "50" },
      { value: 100, text: "100" },
    ],
    pagination: {
      currentPage: 1,
      totalPages: 1,
      totalItems: 0,
      itemsPerPage: 15,
      hasNextPage: false,
      hasPrevPage: false,
    },
  }),

  created() {
    this.fetchLoans(1);
  },

  watch: {
    listType() {
      // Quando o tipo de lista muda (pendente/rejeitado), recarregar
      this.searchQuery = "";
      this.fetchLoans(1);
    },
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "users",
      "token",
      "customers",
      "customersNameMap",
      "currentCustomer",
      "customerLoans",
      "customerTranzactions",
      "company",
    ]),

    statusForApi() {
      if (this.listType === "rejected") return -1;
      return 0; // pending
    },

    pageTotal() {
      return this.loanList.reduce((sum, l) => sum + (parseFloat(l.amount) || 0), 0);
    },

    statusClass() {
      return this.listType === "rejected" ? "bg-soft-danger" : "bg-soft-warning";
    },

    statusIcon() {
      return this.listType === "rejected" ? "x-circle-fill" : "clock-history";
    },

    paginationStart() {
      if (this.pagination.totalItems === 0) return 0;
      return (this.pagination.currentPage - 1) * this.pagination.itemsPerPage + 1;
    },

    paginationEnd() {
      const end = this.pagination.currentPage * this.pagination.itemsPerPage;
      return Math.min(end, this.pagination.totalItems);
    },

    visiblePages() {
      const total = this.pagination.totalPages;
      const current = this.pagination.currentPage;
      const maxVisible = 5;
      const pages = [];
      if (total <= maxVisible) {
        for (let i = 1; i <= total; i++) pages.push(i);
      } else {
        let start = Math.max(1, current - Math.floor(maxVisible / 2));
        let end = start + maxVisible - 1;
        if (end > total) {
          end = total;
          start = Math.max(1, end - maxVisible + 1);
        }
        for (let i = start; i <= end; i++) pages.push(i);
      }
      return pages;
    },

    combinedNameMap() {
      const map = {};
      if (this.customersNameMap) {
        Object.keys(this.customersNameMap).forEach((key) => {
          map[key] = this.customersNameMap[key];
        });
      }
      if (this.customers && this.customers.length > 0) {
        this.customers.forEach((c) => {
          map[c.accountNumber] = c.customerName;
        });
      }
      return map;
    },
  },

  methods: {
    fetchLoans(page = 1) {
      if (!this.company || !this.company.id) return;

      this.loadingLoans = true;
      const params = {
        page,
        limit: this.perPage,
        status: this.statusForApi,
        search: this.searchQuery.trim(),
      };

      // Se não for admin, filtrar por gestor
      if (this.user.userRole !== 1) {
        params.creditManager = this.user.id;
      }

      axios
        .get(`/api/companyLoans/${this.company.id}/paginated`, { params })
        .then((res) => {
          const data = res.data;
          if (data.success) {
            this.loanList = data.result || [];
            if (data.pagination) {
              this.pagination = data.pagination;
            }
          } else {
            this.loanList = [];
            this.pagination = {
              currentPage: 1, totalPages: 0, totalItems: 0,
              itemsPerPage: this.perPage, hasNextPage: false, hasPrevPage: false,
            };
          }
        })
        .catch((err) => {
          console.error("Erro ao carregar financiamentos:", err);
          this.loanList = [];
        })
        .finally(() => {
          this.loadingLoans = false;
        });
    },

    onSearchInput() {
      clearTimeout(this.searchTimeout);
      this.searchTimeout = setTimeout(() => {
        this.fetchLoans(1);
      }, 400);
    },

    clearSearch() {
      this.searchQuery = "";
      this.fetchLoans(1);
    },

    goToPage(page) {
      if (page < 1 || page > this.pagination.totalPages) return;
      if (page === this.pagination.currentPage) return;
      this.fetchLoans(page);
    },

    onPerPageChange() {
      this.fetchLoans(1);
    },

    rowNumber(index) {
      return (this.pagination.currentPage - 1) * this.pagination.itemsPerPage + index + 1;
    },

    getCustomerName(accountNumber) {
      if (this.combinedNameMap[accountNumber]) {
        return this.combinedNameMap[accountNumber];
      }
      return String(accountNumber);
    },

    getCustomerInitials(accountNumber) {
      const name = this.getCustomerName(accountNumber);
      if (!name || name === String(accountNumber)) return "?";
      const parts = name.trim().split(/\s+/);
      if (parts.length >= 2) {
        return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
      }
      return name.charAt(0).toUpperCase();
    },

    getCreditManagerName(managerId) {
      if (!managerId || !this.users || this.users.length === 0) return "—";
      const manager = this.users.find((u) => u.id == managerId);
      return manager ? manager.name : "—";
    },

    avatarVariant(index) {
      const variants = ["primary", "info", "success", "warning", "secondary"];
      return variants[index % variants.length];
    },

    formatMoney(value) {
      return MoneyFormat.formatMoney(value);
    },

    async openCustomerPanel(accountNumber) {
      const filteredCustomer = this.customers.filter(
        (a) => a.accountNumber == accountNumber
      );
      if (filteredCustomer.length > 0) {
        this.$store.commit("SET_CURRENT_CUSTOMER", filteredCustomer[0]);
        this.$router.replace("/customer");
        return;
      }
      try {
        const res = await axios.get(`/api/searchCustomers/${accountNumber}`);
        if (res.data.success && res.data.result.length > 0) {
          const customer = res.data.result.find((c) => c.accountNumber == accountNumber);
          if (customer) {
            this.$store.commit("SET_CURRENT_CUSTOMER", customer);
            this.$router.replace("/customer");
            return;
          }
        }
        this.$bvToast.toast("Mutuário não encontrado.", {
          title: "Aviso!", variant: "warning", solid: true, toaster: "b-toaster-top-center",
        });
      } catch {
        this.$bvToast.toast("Erro ao buscar dados do mutuário.", {
          title: "Erro!", variant: "danger", solid: true, toaster: "b-toaster-top-center",
        });
      }
    },
  },
};
</script>

